public void new(IdentifierName              _className      = classStr(AVACreateCycleCountService),
                IdentifierName              _methodName     = methodStr(AVACreateCycleCountService, create),
                SysOperationExecutionMode   _executionMode  = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

public static AVACreateCycleCountController construct(SysOperationExecutionMode _mode = SysOperationExecutionMode::Synchronous)
{
    AVACreateCycleCountController controller = new AVACreateCycleCountController(classStr(AVACreateCycleCountService), methodStr(AVACreateCycleCountService, create), _mode);

    return controller;
}

private static void main(Args _args)
{
    AVACreateCycleCountController controller;

    controller = AVACreateCycleCountController::construct();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);
    controller.initializeContractFromArgs(_args);
    controller.startOperation();
}

protected void initializeContractFromArgs(Args _args)
{
    AVACreateCycleCountContract   createCycleCountContract;

    if (_args.record())
    {
        createCycleCountContract = this.getDataContractObject();
        createCycleCountContract.parmInitFromRecord(true);
        createCycleCountContract.parmCycleCountGroupBy(AVACycleCountGroupByType::ItemId);
        createCycleCountContract.initFromRecord(_args.record());
    }
}

public boolean showQuerySelectButton(str parameterName)
{
    AVACreateCycleCountContract createCycleCountContract;
    boolean                     ret;

    ret = super(parameterName);

    createCycleCountContract = this.getDataContractObject();

    if (createCycleCountContract.parmInitFromRecord())
    {
        ret = false;
    }

    return ret;
}
